void resetState() {
  require(!state.live && state.tracked.empty() && state.sharedBuffers.empty(), "resource or shared buffer leaked");
  for (unsigned i = 0; i < 3; ++i) {
    require(l4d2_memory::bytes[i] == 0 && l4d2_memory::objects[i] == 0, "shadow memory leaked");
  }
  state = {};
}
