constexpr std::array<Kind, 8> kinds{Kind::VertexBuffer, Kind::IndexBuffer, Kind::RenderTarget,
  Kind::DepthStencilSurface, Kind::OffscreenPlainSurface, Kind::RenderTargetEx,
  Kind::OffscreenPlainSurfaceEx, Kind::DepthStencilSurfaceEx};
template<bool EnableSync>
void testCreation(Kind kind, HRESULT backendResult, bool timeout, bool responses, bool allResponses, bool shared) {
  resetState();
  gpD3DResources.clear();
  state.backendResult = backendResult;
  state.timedOut = timeout;
  state.createResponses = responses;
  state.allResponses = allResponses;
  state.shared = shared;
  const bool wait = responses || allResponses;
  const HRESULT expected = wait ? (timeout ? D3DERR_INVALIDCALL : backendResult) : D3D_OK;
  Direct3DDevice9Ex_LSS<EnableSync> device;
  Outputs output;
  state.outputIsNull = [&] { return output.get(kind) == nullptr; };
  state.requireNullOnRelease = FAILED(expected);
  HANDLE sharedHandle = reinterpret_cast<HANDLE>(9);
  require(create(kind, device, &output, 64, &sharedHandle) == expected, "resource HRESULT changed");
  require(sharedHandle == reinterpret_cast<HANDLE>(9), "existing shared-handle behavior changed");
  require(state.waits == static_cast<unsigned>(wait) && state.pops == static_cast<unsigned>(wait && !timeout),
    "response consumption changed");
  require(!state.messages.empty(), "Create command missing");
  const auto message = state.messages.front();
  require(message.resource == device.getId() && message.arguments.back() == 0x1234,
    "Create command resource handles changed");
  if (wait && !timeout) {
    require(state.hostResponse == backendResult && state.responses == 1 &&
      gpD3DResources.size() == static_cast<size_t>(SUCCEEDED(backendResult)), "Host failure/success registration changed");
    auto expectedArguments = message.arguments;
    expectedArguments.pop_back();
    require(state.backendArguments == expectedArguments, "Host API arguments differ from transmitted fields");
  }
  if (FAILED(expected)) {
    require(!output.get(kind) && !state.live && state.tracked.empty() && state.releases == 1,
      "failed creation retained output, wrapper or tracked state");
  } else {
    require(output.get(kind) && state.live == 1 && state.tracked.size() == 1 && !state.releases && device.references == 2,
      "successful creation lost caller or parent ownership");
    const bool buffer = kind == Kind::VertexBuffer || kind == Kind::IndexBuffer;
    const auto shadowBytes = l4d2_memory::bytes[1].load() + l4d2_memory::bytes[2].load();
    require(shadowBytes == (buffer && !shared ? 64u : 0u), "buffer shadow allocation policy changed");
    output.get(kind)->Release();
  }
  require(device.references == 1, "resource release retained its parent device");
  const bool destroy = SUCCEEDED(expected) || timeout;
  require(state.messages.size() == (destroy ? 2u : 1u), "explicit failure or timeout Destroy handling changed");
  if (destroy) {
    const auto& last = state.messages.back();
    const auto command = kind == Kind::VertexBuffer ? Commands::IDirect3DVertexBuffer9_Destroy :
      kind == Kind::IndexBuffer ? Commands::IDirect3DIndexBuffer9_Destroy : Commands::IDirect3DSurface9_Destroy;
    require(last.command == command && last.resource == 0x1234 && last.uid > message.uid,
      "Destroy was not ordered after its Create");
  }
  resetState();
}
template<bool EnableSync> void testCreations() {
  for (const auto kind : kinds) {
    for (const bool shared : {false, true}) {
      for (const auto result : {D3D_OK, D3DERR_INVALIDCALL, D3DERR_OUTOFVIDEOMEMORY, E_OUTOFMEMORY}) {
        testCreation<EnableSync>(kind, result, false, true, false, shared);
        testCreation<EnableSync>(kind, result, false, false, true, shared);
      }
      testCreation<EnableSync>(kind, D3D_OK, true, true, false, shared);
      testCreation<EnableSync>(kind, D3DERR_OUTOFVIDEOMEMORY, false, false, false, shared);
    }
    for (unsigned i = 0; i < 50; ++i) {
      testCreation<EnableSync>(kind, D3DERR_OUTOFVIDEOMEMORY, false, true, false, false);
    }
    resetState();
    Direct3DDevice9Ex_LSS<EnableSync> device;
    require(create(kind, device, nullptr, 64, nullptr) == D3DERR_INVALIDCALL && state.messages.empty() && !state.live,
      "null output created or transmitted a resource");
    if (kind == Kind::VertexBuffer || kind == Kind::IndexBuffer || kind == Kind::RenderTarget || kind == Kind::DepthStencilSurface) {
      Outputs output;
      require(create(kind, device, &output, 0, nullptr) == D3DERR_INVALIDCALL && !output.get(kind) && state.messages.empty(),
        "zero-dimension validation did not clear its output");
    }
  }
}

template<typename Buffer, typename Desc>
void testLocks(const Desc& descriptor, bool shared, bool optimized, bool whole) {
  resetState();
  state.shared = shared;
  state.optimized = optimized;
  state.sendWhole = whole;
  BaseDirect3DDevice9Ex_LSS device;
  auto* buffer = trackWrapper(new Buffer(&device, descriptor));
  for (const UINT offset : {65u, (std::numeric_limits<UINT>::max)()}) {
    for (const UINT size : {0u, 1u, (std::numeric_limits<UINT>::max)()}) {
      void* pointer = reinterpret_cast<void*>(1);
      const auto allocations = state.allocations;
      require(buffer->lock(offset, size, &pointer, D3DLOCK_DISCARD) == D3DERR_INVALIDCALL && pointer == nullptr,
        "out-of-range offset was accepted");
      buffer->unlock();
      require(state.allocations == allocations && state.messages.empty(), "invalid lock allocated or queued a command");
    }
  }
  require(buffer->lock(0, 0, nullptr, 0) == D3DERR_INVALIDCALL, "null lock output was accepted");
  for (const UINT offset : {0u, 7u, 64u}) {
    for (const UINT requested : {0u, 5u, 128u, (std::numeric_limits<UINT>::max)()}) {
      state.messages.clear();
      void* pointer = nullptr;
      require(buffer->lock(offset, requested, &pointer, 0) == D3D_OK && pointer,
        "valid offset or tolerated oversized request was rejected");
      const size_t size = requested ? (std::min)(requested, 64u - offset) : 64u - offset;
      std::memset(pointer, 0x5a, size);
      buffer->unlock();
      require(!state.messages.empty(), "valid lock upload missing");
      const auto& upload = state.messages.back();
      const bool sendWhole = whole && (descriptor.Usage & D3DUSAGE_DYNAMIC) == 0;
      const size_t expectedSize = sendWhole ? 64 : size;
      require(upload.arguments[0] == (sendWhole ? 0u : offset) && upload.arguments[1] == expectedSize,
        "lock upload range changed");
      if (!shared && !optimized) {
        require(upload.bytes.size() == expectedSize, "shadow upload byte count changed");
        if (!sendWhole) {
          require(std::all_of(upload.bytes.begin(), upload.bytes.end(), [](uint8_t value) { return value == 0x5a; }),
            "shadow upload contents changed");
        }
      }
    }
  }
  state.messages.clear();
  void* pointer = nullptr;
  for (unsigned i = 0; i < 2; ++i) {
    require(buffer->lock(0, 8, &pointer, D3DLOCK_DISCARD) == D3D_OK, "discard lock failed");
    std::memset(pointer, 0x7b, 8);
    buffer->unlock();
  }
  state.messages.clear();
  require(buffer->lock(0, 8, &pointer, D3DLOCK_READONLY) == D3D_OK, "read-only lock failed");
  const size_t before = state.messages.size();
  buffer->unlock();
  require(state.messages.size() == before, "read-only unlock uploaded data");
  buffer->Release();
  require(device.references == 1 && state.allocations == state.deallocations, "buffer cleanup leaked references or shared storage");
  resetState();
}
template<typename Buffer, typename Desc> void testPolicy(const Desc& descriptor) {
  resetState();
  state.shared = true;
  state.sharedDynamic = false;
  state.sharedStatic = true;
  BaseDirect3DDevice9Ex_LSS device;
  // Poison the future m_desc storage so reading it before initialization chooses
  // the wrong policy deterministically, instead of relying on stack contents.
  alignas(Buffer) unsigned char storage[sizeof(Buffer)];
  std::memset(storage, 0xff, sizeof(storage));
  auto* buffer = new (static_cast<void*>(storage)) Buffer(&device, descriptor);
  require(l4d2_memory::bytes[1] == 0 && l4d2_memory::bytes[2] == 0,
    "shared policy read an uninitialized resource descriptor");
  void* pointer = nullptr;
  require(buffer->lock(65, 0, &pointer, 0) == D3DERR_INVALIDCALL && !state.allocations && state.messages.empty(),
    "shared policy invalid offset touched transport or allocations");
  buffer->~Buffer();
  device.Release();
  resetState();
}
int main() {
  // Async sampling/lifetime is exercised in memory_sampling_async.cpp. Keep
  // these ownership tests free of callbacks during executable CRT teardown.
  l4d2_memory::nextSample.store((std::numeric_limits<ULONGLONG>::max)());
  l4d2_observation::memoryMonitoring = true;
  try {
    testCreations<false>();
    testCreations<true>();
    for (const DWORD usage : {DWORD(0), DWORD(D3DUSAGE_DYNAMIC)}) {
      const D3DVERTEXBUFFER_DESC vertex{D3DFMT_VERTEXDATA, D3DRTYPE_VERTEXBUFFER, usage, D3DPOOL_DEFAULT, 64, 0};
      const D3DINDEXBUFFER_DESC index{D3DFMT_INDEX16, D3DRTYPE_INDEXBUFFER, usage, D3DPOOL_DEFAULT, 64};
      for (const bool shared : {false, true}) {
        testLocks<Direct3DVertexBuffer9_LSS>(vertex, shared, false, false);
        testLocks<Direct3DIndexBuffer9_LSS>(index, shared, false, false);
      }
      if (usage) {
        testLocks<Direct3DVertexBuffer9_LSS>(vertex, false, true, false);
        testLocks<Direct3DIndexBuffer9_LSS>(index, false, true, false);
      } else {
        testLocks<Direct3DVertexBuffer9_LSS>(vertex, false, false, true);
        testLocks<Direct3DIndexBuffer9_LSS>(index, false, false, true);
        testPolicy<Direct3DVertexBuffer9_LSS>(vertex);
        testPolicy<Direct3DIndexBuffer9_LSS>(index);
      }
    }
    std::puts("PASS: actual resource Create/Release/destruction, shadow ownership, Host responses and buffer locks; failure/timeout/async, shared policies and offset/oversized boundaries.");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
